rules.logic:
if (element.querySelector('.language-filter-bar')) return;

var section = element;
var tower = section.querySelector('.tw-tower');
if (!tower) return;

// Collect all language tags from stream cards
var articles = section.querySelectorAll('article.ghbJdj');
var langMap = {};
articles.forEach(function(article) {
  var tags = article.querySelectorAll('[class*="ScTag-sc-ajnfk3"]');
  tags.forEach(function(tagLink) {
    var target = tagLink.getAttribute('data-a-target');
    if (target) {
      langMap[target] = true;
    }
  });
});

var languages = Object.keys(langMap).sort();
if (languages.length === 0) return;

// Create filter bar
var filterBar = document.createElement('div');
filterBar.className = 'language-filter-bar';
filterBar.style.cssText = 'display:flex;align-items:center;gap:0.5rem;padding:0.75rem 1rem;margin-bottom:0.5rem;background:#1a1a2a;border-radius:8px;border:1px solid #3a3a4a;font-family:var(--font-body);';

var label = document.createElement('span');
label.style.cssText = 'color:#fff;font-weight:600;font-size:0.9rem;white-space:nowrap;';
label.textContent = '🌐 Filter by language:';
filterBar.appendChild(label);

var select = document.createElement('select');
select.id = 'language-filter-select';
select.style.cssText = 'padding:0.4rem 2rem 0.4rem 0.6rem;border-radius:4px;border:1px solid #555;background:#0e0e1a;color:#fff;font-size:0.85rem;cursor:pointer;min-width:140px;appearance:auto;';

var allOption = document.createElement('option');
allOption.value = '__all__';
allOption.textContent = 'All languages';
select.appendChild(allOption);

languages.forEach(function(lang) {
  var opt = document.createElement('option');
  opt.value = lang;
  opt.textContent = lang;
  select.appendChild(opt);
});

filterBar.appendChild(select);

// Insert before tower
tower.parentNode.insertBefore(filterBar, tower);

// Apply filter function
function applyFilter() {
  var selectedLang = select.value;
  articles.forEach(function(article) {
    if (selectedLang === '__all__') {
      article.style.display = '';
      return;
    }
    var hasTag = false;
    var tags = article.querySelectorAll('[class*="ScTag-sc-ajnfk3"]');
    tags.forEach(function(tagLink) {
      if (tagLink.getAttribute('data-a-target') === selectedLang) {
        hasTag = true;
      }
    });
    article.style.display = hasTag ? '' : 'none';
  });
}

select.addEventListener('change', applyFilter);
